import { Star, ThumbsUp } from "lucide-react"
import { Progress } from "@/components/ui/progress"

interface Review {
    id: number
    author: string
    date: string
    rating: number
    text: string
    helpful: number
}

interface ProductReviewsProps {
    reviews: Review[]
    rating: number
    totalReviews: number
}

export default function ProductReviews({ reviews, rating, totalReviews }: ProductReviewsProps) {
    return (
        <section id="reviews" className="space-y-8">
            <h2 className="text-2xl font-bold">Customer Reviews</h2>

            <div className="grid md:grid-cols-3 gap-8">
                {/* Summary */}
                <div className="md:col-span-1 space-y-6">
                    <div className="text-center md:text-left">
                        <div className="text-5xl font-bold text-foreground mb-2">{rating}</div>
                        <div className="flex justify-center md:justify-start gap-1 mb-2">
                            {[...Array(5)].map((_, i) => (
                                <Star
                                    key={i}
                                    className={`w-5 h-5 ${i < Math.floor(rating) ? "fill-accent text-accent" : "text-border"
                                        }`}
                                />
                            ))}
                        </div>
                        <p className="text-muted-foreground">{totalReviews} verified reviews</p>
                    </div>

                    <div className="space-y-2">
                        {[5, 4, 3, 2, 1].map((star) => (
                            <div key={star} className="flex items-center gap-3 text-sm">
                                <span className="w-3 font-medium">{star}</span>
                                <Star className="w-4 h-4 text-muted-foreground" />
                                <Progress value={star === 5 ? 70 : star === 4 ? 20 : 5} className="h-2" />
                                <span className="w-8 text-right text-muted-foreground">
                                    {star === 5 ? "70%" : star === 4 ? "20%" : "5%"}
                                </span>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Reviews List */}
                <div className="md:col-span-2 space-y-6">
                    {reviews.map((review) => (
                        <div key={review.id} className="border-b border-border pb-6 last:border-0">
                            <div className="flex items-center justify-between mb-2">
                                <div className="flex items-center gap-2">
                                    <div className="font-semibold">{review.author}</div>
                                    <span className="text-xs text-muted-foreground">• {review.date}</span>
                                </div>
                                <div className="flex gap-0.5">
                                    {[...Array(5)].map((_, i) => (
                                        <Star
                                            key={i}
                                            className={`w-3.5 h-3.5 ${i < review.rating ? "fill-accent text-accent" : "text-border"
                                                }`}
                                        />
                                    ))}
                                </div>
                            </div>
                            <p className="text-muted-foreground text-sm mb-4">{review.text}</p>
                            <button className="flex items-center gap-2 text-xs text-muted-foreground hover:text-foreground transition">
                                <ThumbsUp className="w-3.5 h-3.5" />
                                Helpful ({review.helpful})
                            </button>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    )
}
